package xyz.rimvisuals;
import org.junit.jupiter.api.Test;
import xyz.rimvisuals.core.HelperTracker;
import static org.junit.jupiter.api.Assertions.*;
class HelperTrackerTest {
 @Test void parsesPublishedWireShapeWithoutInventingTimes(){var list=HelperTracker.api("{\"LITE_ANARCHY_1\":[{\"instanceId\":\"i1\",\"id\":\"cube\",\"metadata\":{\"displayName\":\"Куб\",\"rare\":\"epic\"}}]}",1000);assertEquals(1,list.size());var e=list.getFirst();assertEquals("Куб",e.name());assertEquals(HelperTracker.State.ACTIVE,e.state());assertEquals(0,e.start());assertEquals(0,e.end());assertEquals("time unknown",e.countdown(1000));assertEquals("",e.coordinates());}
 @Test void malformedApiCannotCreateEvents(){assertThrows(RuntimeException.class,()->HelperTracker.api("oops",0));assertThrows(RuntimeException.class,()->HelperTracker.api("[]",0));assertThrows(RuntimeException.class,()->HelperTracker.api("x".repeat(262145),0));assertTrue(HelperTracker.api("{}",0).isEmpty());assertTrue(HelperTracker.api("{\"x\":[{},null,42]}",0).isEmpty());}
 @Test void messageTimesAndCoordinatesAreReceivedOnly(){var t=new HelperTracker();assertFalse(t.message("unrelated chat","Вулкан","s",1000));assertTrue(t.message("Вулкан начнется через 2 мин 10 сек анархия #12 координаты: 100 64 -50","Вулкан","s",1000));var e=t.events.values().iterator().next();assertEquals(HelperTracker.State.UPCOMING,e.state());assertEquals(131000,e.start());assertEquals("Anarchy #12",e.server());assertEquals("100 64 -50",e.coordinates());assertFalse(t.message("Вулкан начнется через 2 мин 10 сек анархия #12 координаты: 100 64 -50","Вулкан","s",1500));}
 @Test void durationBounds(){assertEquals(90,HelperTracker.duration("до начала 1:30"));assertEquals(3723,HelperTracker.duration("01:02:03"));assertEquals(130,HelperTracker.duration("2 мин 10 сек"));assertEquals(-1,HelperTracker.duration("unknown"));assertEquals(-1,HelperTracker.duration("99:99"));assertEquals(-1,HelperTracker.duration("9999 часов"));}
 @Test void cooldownReadyOnceAndEstimateExplicit(){var t=new HelperTracker();t.cooldown("Trapka",2,true,"attempt",1000);var cd=t.cooldowns.get("Trapka");assertTrue(cd.estimated());assertEquals(2,cd.seconds(1000));assertEquals(.5,cd.progress(2000),1e-8);assertTrue(t.ready(2500).isEmpty());assertEquals(1,t.ready(3000).size());assertTrue(t.ready(4000).isEmpty());t.cooldown("Trapka",5,false,"server packet",4000);assertFalse(t.cooldowns.get("Trapka").estimated());assertTrue(t.ready(5000).isEmpty());t.clear();assertTrue(t.cooldowns.isEmpty());assertTrue(t.events.isEmpty());}
 @Test void disappearanceIsNotFabricatedFinish(){var t=new HelperTracker();t.replaceApi(HelperTracker.api("{\"s\":[{\"instanceId\":\"1\",\"metadata\":{\"displayName\":\"Event\"}}]}",1000),1000);t.replaceApi(java.util.List.of(),2000);assertEquals(HelperTracker.State.UNKNOWN,t.events.values().iterator().next().state());}
 @Test void filtersAndLimits(){assertTrue(HelperTracker.interested("Вулкан","вулкан,гейзер"));assertFalse(HelperTracker.interested("Вулкан","Куб"));var t=new HelperTracker();for(int i=0;i<500;i++)t.message("Вулкан начался анархия #"+i,"Вулкан","s",10000+i);assertTrue(t.events.size()<=64);}
}
